// VPJ candidate experience. All personal activity is browser-local.
let jobTabVPJ='all',companyLimitVPJ=24,followingOnlyVPJ=false,selectedCompanyVPJ='';
let followedVPJ=read('vpj_followed_companies',[]),recentVPJ=read('vpj_recent',[]),trackerVPJ=read('vpj_tracker',[]),historyVPJ=read('vpj_search_history',[]);
const trackerStatusesVPJ=['Đang cân nhắc','Đã gửi hồ sơ','Phỏng vấn','Nhận việc','Không tiếp tục'];
const detailCacheVPJ=new Map();let detailRequestVPJ=0;let suggestionTimerVPJ;
function companyKeyVPJ(j){return j.companySlug||j.company}
function keywordTextVPJ(j){return norm([j.title,j.company,j.address,j.category,...(j.positions||[]),...(j.skills||[])].join(' '))}
const filterBeforeExperienceVPJ=publicFilteredVPJ;
publicFilteredVPJ=function(){return filterBeforeExperienceVPJ().filter(j=>!selectedCompanyVPJ||companyKeyVPJ(j)===selectedCompanyVPJ).filter(j=>jobTabVPJ==='all'||(jobTabVPJ==='salary'&&j.max>0)||(jobTabVPJ==='open'&&j.deadline&&!deadlineExpiredVPJ(j))||(jobTabVPJ==='logos'&&j.logoUrl))};
const cardBeforeExperienceVPJ=card;
card=function(j){let html=cardBeforeExperienceVPJ(j);if(!j.sourceUrl)return html;const roles=(j.positions||[]).slice(0,2),skills=(j.skills||[]).slice(0,4);html=html.replace('<div class="tags">',`${roles.length?`<div class="job-roles">${roles.map(esc).join(' · ')}${j.positionCount>2?` · +${j.positionCount-2} vị trí`:''}</div>`:''}${skills.length?`<div class="skill-chips">${skills.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div class="tags">`);return html.replace('<label class="compare-toggle">','<div class="job-quick-actions"><label class="compare-toggle">').replace('</label></article>',`</label><button data-trackjob="${j.id}">${trackerVPJ.some(t=>t.jobId===j.id)?'✓ Đang theo dõi':'＋ Theo dõi'}</button></div></article>`)};
function renderActivityVPJ(){const n=trackerVPJ.filter(t=>t.status==='Phỏng vấn').length;$('#activitySummary').innerHTML=`<div class="activity-counts"><div><strong>${saved.length}</strong><small>Đã lưu</small></div><div><strong>${trackerVPJ.length}</strong><small>Theo dõi</small></div><div><strong>${n}</strong><small>Phỏng vấn</small></div></div>`;$('#recentJobs').innerHTML=recentVPJ.map(id=>jobs.find(j=>j.id===id)).filter(Boolean).slice(0,4).map(j=>`<button class="recent-item" data-detail="${j.id}">${esc(j.title)}<small>${esc(j.location)} · ${esc(j.company)}</small></button>`).join('')||'<p class="source-empty">Tin bạn mở sẽ xuất hiện tại đây.</p>'}
function filterChipVPJ(text,key,value=''){return `<button data-clearfilter="${esc(key)}" data-filtervalue="${esc(value)}">${esc(text)} <span>×</span></button>`}
function renderFilterChipsVPJ(){let chips=[];if(selectedCompanyVPJ){const c=getCompaniesVPJ().find(c=>c.key===selectedCompanyVPJ);if(c)chips.push(filterChipVPJ(c.job.company,'company'))}if($('#query').value)chips.push(filterChipVPJ($('#query').value,'query'));if($('#location').value)chips.push(filterChipVPJ($('#location').value,'location'));if(+$('#salaryFilter').value)chips.push(filterChipVPJ('Có vị trí từ '+$('#salaryFilter').value+' triệu','salary'));if($('#experienceFilter').value)chips.push(filterChipVPJ($('#experienceFilter').value==='none'?'Không cần kinh nghiệm':'Có kinh nghiệm','experience'));$$('input[name=category]:checked').forEach(e=>chips.push(filterChipVPJ(e.value,'category',e.value)));$$('input[name=type]:checked').forEach(e=>chips.push(filterChipVPJ(e.value,'type',e.value)));$('#activeFilters').innerHTML=chips.join('');$$('[data-jobtab]').forEach(e=>e.classList.toggle('active',e.dataset.jobtab===jobTabVPJ))}
function setJobLayoutVPJ(layout){write('vpj_job_layout',layout);$('#jobCards').classList.toggle('list-layout',layout==='list');$$('[data-joblayout]').forEach(e=>{e.classList.toggle('active',e.dataset.joblayout===layout);e.setAttribute('aria-pressed',String(e.dataset.joblayout===layout))})}
function refreshProfileProgressVPJ(){const fields=['profileName','profilePhone','profileEmail','profileSkills','profileJob','profileAbout'];const filled=fields.filter(id=>$('#'+id).value.trim()).length,percent=Math.round(filled/fields.length*100);$('#profilePercent').textContent=percent+'%';$('#profileProgress').style.width=percent+'%';$('#profileHint').textContent=percent===100?'Hồ sơ đã có đầy đủ 6 nhóm thông tin. Bạn có thể tạo CV PDF.':'Còn '+(fields.length-filled)+' nhóm thông tin. Thêm kỹ năng và vị trí mong muốn để gợi ý sát hơn.'}
function buildNotificationMatchesVPJ(){let found=new Map();for(const j of jobs.filter(j=>j.sourceUrl&&j.days<=60)){const company=followedVPJ.includes(companyKeyVPJ(j));const match=searchesVPJ.some(s=>(!s.company||s.company===companyKeyVPJ(j))&&(!s.query||keywordTextVPJ(j).includes(norm(s.query)))&&(!s.location||s.location===j.location)&&(!s.categories?.length||s.categories.includes(j.category))&&(!+s.salary||j.min>=+s.salary)&&(!s.experience||(j.experienceFlags||[]).includes(s.experience))&&(!s.types?.length||s.types.includes(j.type)));if(company||match)found.set(j.id,{j,reason:company?'Công ty bạn đang theo dõi':'Khớp tìm kiếm đã lưu'})}return [...found.values()].sort((a,b)=>a.j.days-b.j.days).slice(0,30)}
function renderNotificationBadgeVPJ(){const n=buildNotificationMatchesVPJ().length;$('#notificationBadge').hidden=!n;$('#notificationBadge').textContent=n>9?'9+':n}
function showNotificationsVPJ(){const matches=buildNotificationMatchesVPJ();openModal(`<h2>Thông báo tìm việc</h2><p>Gợi ý trong kho tin khớp tìm kiếm đã lưu và doanh nghiệp bạn theo dõi. Chưa gửi thông báo qua email, SMS hoặc thông báo đẩy.</p><div class="notification-section"><h3>${matches.length?matches.length+' tin gợi ý gần đây':'Bạn chưa có tin gợi ý'}</h3>${matches.map(({j,reason})=>`<button class="notification-item" data-detail="${j.id}">${esc(j.title)}<small>${esc(reason)} · ${esc(j.location)} · Đăng ${esc(j.published.split('-').reverse().join('/'))}</small></button>`).join('')||'<p class="source-empty">Lưu một tìm kiếm hoặc theo dõi doanh nghiệp để xem tin liên quan tại đây.</p>'}</div><div class="actions"><button class="btn" data-showsavedsearches>Quản lý tìm kiếm đã lưu</button><button class="btn" data-view="companies">Khám phá doanh nghiệp</button></div>`,true)}
function getCompaniesVPJ(){const map=new Map();for(const j of jobs.filter(x=>x.sourceUrl)){const key=companyKeyVPJ(j);if(!map.has(key))map.set(key,{key,job:j,count:0,recentCount:0});const c=map.get(key);c.count++;if(j.days<=60)c.recentCount++}return [...map.values()]}
function filteredCompaniesVPJ(){const q=norm($('#companySearch').value.trim()),region=$('#companyRegion').value;return getCompaniesVPJ().filter(c=>(!q||norm(c.job.company+' '+c.job.location).includes(q))&&(!region||c.job.location===region)&&(!followingOnlyVPJ||followedVPJ.includes(c.key)))}
function companyFollowButtonVPJ(key){const yes=followedVPJ.includes(key);return `<button class="follow-company ${yes?'followed':''}" data-followcompany="${esc(key)}" aria-pressed="${yes}">${yes?'✓ Đang theo dõi':'＋ Theo dõi'}</button>`}
renderPublicCompaniesVPJ=function(){const all=getCompaniesVPJ(),list=filteredCompaniesVPJ();companies.splice(0,companies.length,...all.map(c=>c.job));$('#companyCount').textContent=`${list.length.toLocaleString('vi-VN')} doanh nghiệp / nhóm tin · Hiển thị ${Math.min(companyLimitVPJ,list.length)} đơn vị`;$('#companyCards').innerHTML=list.slice(0,companyLimitVPJ).map(c=>`<article class="company-profile-card"><div class="company-cover">${companyFollowButtonVPJ(c.key)}</div><div class="company-profile-body">${avatarVPJ(c.job)}<h3>${esc(c.job.company)}</h3><p>⌖ ${esc(c.job.location)}</p><div class="company-card-meta"><span>${c.count} tin trong kho${c.recentCount?` · ${c.recentCount} tin gần đây`:''}</span><button data-companyprofile="${esc(c.key)}">Xem công ty ↗</button></div></div></article>`).join('')||'<div class="empty">Chưa có công ty phù hợp với lựa chọn.</div>';$('#companyMore').style.display=list.length>companyLimitVPJ?'inline-flex':'none';$('#companyMore').textContent=`Xem thêm 24 công ty (${Math.min(companyLimitVPJ,list.length)}/${list.length}) ↓`;$('#employerShowcase').innerHTML=all.filter(c=>c.job.logoUrl).slice(0,6).map(c=>`<button class="employer-tile" data-companyprofile="${esc(c.key)}">${avatarVPJ(c.job)}<h3>${esc(c.job.company)}</h3><small>${esc(c.job.location)} · ${c.recentCount} tin gần đây</small></button>`).join('')};
function showCompanyProfileVPJ(key){const c=getCompaniesVPJ().find(x=>x.key===key);if(!c)return;const list=jobs.filter(j=>companyKeyVPJ(j)===key);openModal(`<div class="detail-hero"><div class="job-top">${avatarVPJ(c.job)}<div><span class="eyebrow">HỒ SƠ DOANH NGHIỆP TỪ NGUỒN</span><h2>${esc(c.job.company)}</h2><p>⌖ ${esc(c.job.location)}</p>${companyFollowButtonVPJ(key)}</div></div><div class="detail-meta-grid"><div><small>Kho tin công khai</small><b>${c.count} tin</b></div><div><small>60 ngày gần đây</small><b>${c.recentCount} tin</b></div><div><small>Khu vực</small><b>${esc(c.job.location)}</b></div></div></div>${c.job.companyUrl?`<a class="btn" href="${esc(c.job.companyUrl)}" target="_blank" rel="noopener noreferrer">Thông tin công ty tại nguồn ↗</a>`:''}<div class="detail-section"><h3>Tin mới nhất của công ty</h3><div class="detail-related">${list.slice(0,8).map(j=>`<button data-detail="${j.id}"><b>${esc(j.title)}</b>${esc(j.salaryText)}<br>Đăng ${esc(j.published.split('-').reverse().join('/'))}</button>`).join('')}</div><button class="btn" style="margin-top:18px" data-companyjobs="${esc(key)}">Xem toàn bộ ${c.count} tin ↓</button></div><p class="detail-note">Thông tin từ kho công khai. Số tin không đồng nghĩa với số vị trí hiện còn tuyển; kiểm tra hạn và tin gốc trước khi ứng tuyển.</p>`,true)}
function toggleFollowVPJ(key){followedVPJ=followedVPJ.includes(key)?followedVPJ.filter(x=>x!==key):[...followedVPJ,key];write('vpj_followed_companies',followedVPJ);renderPublicCompaniesVPJ();renderNotificationBadgeVPJ();$$('[data-followcompany]').filter(b=>b.dataset.followcompany===key).forEach(b=>{const yes=followedVPJ.includes(key);b.textContent=yes?'✓ Đang theo dõi':'＋ Theo dõi';b.classList.toggle('followed',yes);b.setAttribute('aria-pressed',String(yes))});toast(followedVPJ.includes(key)?'Đã theo dõi công ty trên thiết bị':'Đã bỏ theo dõi công ty')}
function trackJobVPJ(id){if(trackerVPJ.some(t=>t.jobId===id)){closeModal();view('tracker');return}const j=jobs.find(j=>j.id===id);if(!j)return;trackerVPJ.unshift({jobId:id,status:'Đang cân nhắc',note:'',updatedAt:new Date().toISOString()});write('vpj_tracker',trackerVPJ);renderTrackerVPJ();renderActivityVPJ();toast('Đã thêm vào danh sách theo dõi. Chưa gửi hồ sơ.');render()}
function renderTrackerVPJ(){const rows=trackerVPJ.map(t=>({t,j:jobs.find(j=>j.id===t.jobId)})).filter(x=>x.j),filter=$('#trackerFilter').value;$('#trackerSummary').innerHTML=[[rows.length,'Cơ hội đang theo dõi'],[rows.filter(x=>x.t.status==='Đã gửi hồ sơ').length,'Đã gửi hồ sơ'],[rows.filter(x=>x.t.status==='Phỏng vấn').length,'Phỏng vấn'],[rows.filter(x=>x.t.status==='Nhận việc').length,'Nhận việc']].map(([n,t])=>`<div><b>${n}</b><span>${t}</span></div>`).join('');const list=rows.filter(x=>!filter||x.t.status===filter);$('#trackerList').innerHTML=list.map(({t,j})=>`<article class="tracker-row">${avatarVPJ(j)}<div><h3><button class="detail-button" style="font-size:inherit;text-align:left" data-detail="${j.id}">${esc(j.title)}</button></h3><p>${esc(j.company)} · ${esc(j.location)}</p><textarea data-tracknote="${j.id}" maxlength="1500" placeholder="Ghi chú: ngày gửi CV, lịch hẹn, người liên hệ…" aria-label="Ghi chú cho ${esc(j.title)}">${esc(t.note||'')}</textarea><div class="tracker-date">Cập nhật ${new Date(t.updatedAt).toLocaleDateString('vi-VN')}</div></div><div><select data-trackstatus="${j.id}" aria-label="Trạng thái ${esc(j.title)}">${trackerStatusesVPJ.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><button class="tracker-remove" data-untrack="${j.id}">Xóa khỏi danh sách</button></div></article>`).join('')||`<div class="tracker-empty"><div class="empty-icon">◎</div><h3>${rows.length?'Chưa có tin ở trạng thái này':'Bắt đầu hành trình mới.'}</h3><p>Mở một tin tuyển dụng và chọn “Theo dõi”. Khi đã gửi hồ sơ tại nguồn, bạn tự cập nhật trạng thái và lịch phỏng vấn tại đây.</p><button class="btn primary" data-view="jobs">Tìm công việc phù hợp ↗</button></div>`}
function exportTrackerVPJ(){if(!trackerVPJ.length){toast('Chưa có tin để xuất');return}const cell=x=>{let s=String(x||'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const rows=[['Vị trí','Công ty','Địa điểm','Trạng thái','Ghi chú','Cập nhật','Nguồn'],...trackerVPJ.map(t=>{const j=jobs.find(j=>j.id===t.jobId);return j?[j.title,j.company,j.location,t.status,t.note,t.updatedAt,j.sourceUrl||'']:null}).filter(Boolean)];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='VPJ-theo-doi-ung-tuyen.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất danh sách CSV')}
function addSearchHistoryVPJ(){const q=$('#query').value.trim();if(!q)return;historyVPJ=[q,...historyVPJ.filter(x=>norm(x)!==norm(q))].slice(0,8);write('vpj_search_history',historyVPJ)}
function searchSuggestionsVPJ(){const q=norm($('#query').value.trim()),suggestions=[];if(!q){historyVPJ.slice(0,5).forEach(t=>suggestions.push({text:t,kind:'Gần đây',query:t}))}else{const companyNames=[...new Set(jobs.filter(j=>norm(j.company).includes(q)).map(j=>j.company))];companyNames.slice(0,3).forEach(t=>suggestions.push({text:t,kind:'Công ty',query:t}));const roles=[...new Set(jobs.flatMap(j=>j.positions||[]).filter(t=>norm(t).includes(q)))];roles.slice(0,4).forEach(t=>suggestions.push({text:t,kind:'Vị trí',query:t}));if(!suggestions.length)jobs.filter(j=>keywordTextVPJ(j).includes(q)).slice(0,5).forEach(j=>suggestions.push({text:j.title,kind:j.location,id:j.id}))}$('#searchSuggestions').innerHTML=suggestions.length?'<span>'+(q?'GỢI Ý TÌM KIẾM':'TÌM KIẾM GẦN ĐÂY')+'</span>'+suggestions.map(s=>`<button class="suggestion-item" ${s.id?`data-detail="${s.id}"`:`data-suggestion="${esc(s.query)}"`}><span>⌕</span>${esc(s.text)}<small>${esc(s.kind)}</small></button>`).join(''):'';$('#searchSuggestions').hidden=!suggestions.length;$('#query').setAttribute('aria-expanded',String(Boolean(suggestions.length)))}
function hideSuggestionsVPJ(){$('#searchSuggestions').hidden=true;$('#query').setAttribute('aria-expanded','false')}
function saveSearchVPJ(){const entry={id:Date.now(),query:$('#query').value.trim(),location:$('#location').value,salary:$('#salaryFilter').value,categories:$$('input[name=category]:checked').map(x=>x.value),types:$$('input[name=type]:checked').map(x=>x.value),experience:$('#experienceFilter').value,period:$('#periodFilter').value,tab:jobTabVPJ,company:selectedCompanyVPJ};searchesVPJ.push(entry);write('vpj_searches',searchesVPJ);renderNotificationBadgeVPJ();showSearchesVPJ()}
showSearchesVPJ=function(){openModal(`<h2>Tìm kiếm đã lưu</h2><p>Mở lại đầy đủ bộ lọc. Chuông VPJ gợi ý tin khớp trong kho trên thiết bị này.</p>${searchesVPJ.map(s=>`<div class="notification-item"><b>${esc(s.query||'Tất cả công việc')}</b><small>${esc(s.location||'Tất cả khu vực')} · ${s.period==='all'?'Toàn bộ kho tin':(s.period||60)+' ngày gần đây'}${+s.salary?' · Có vị trí từ '+s.salary+' triệu':''}</small><div class="actions" style="margin-top:12px"><button class="btn" data-restoresaved="${s.id}">Tìm lại</button><button class="btn" data-deletesaved="${s.id}">Xóa</button></div></div>`).join('')||'<p class="source-empty">Chưa có tìm kiếm được lưu. Chọn bộ lọc và bấm “Lưu tìm kiếm”.</p>'}`,true)};
function restoreSearchVPJ(id){const s=searchesVPJ.find(s=>s.id===id);if(!s)return;reset();$('#query').value=s.query;$('#location').value=s.location;$('#salaryFilter').value=s.salary;$('#experienceFilter').value=s.experience;$('#periodFilter').value=s.period||'60';jobTabVPJ=s.tab||'all';selectedCompanyVPJ=s.company||'';$$('input[name=category]').forEach(e=>e.checked=(s.categories||[]).includes(e.value));$$('input[name=type]').forEach(e=>e.checked=(s.types||[]).includes(e.value));closeModal();view('jobs');render()}
function recommendationItemsVPJ(){const tokens=norm((profile.skills||'')+' '+(profile.job||'')).split(/[\s,;/]+/).filter(t=>t.length>=3);if(!tokens.length)return [];return jobs.filter(j=>j.sourceUrl&&j.days<=60).map(j=>({j,score:tokens.reduce((n,t)=>n+(keywordTextVPJ(j).includes(t)?1:0),0)})).filter(x=>x.score).sort((a,b)=>b.score-a.score||a.j.days-b.j.days).slice(0,3).map(x=>x.j)}
function renderRecommendationsVPJ(){const host=$('#recommendationSlot');if(!host)return;const list=recommendationItemsVPJ();host.innerHTML=list.length?`<div class="recommendation-card"><h3>Gợi ý theo kỹ năng của bạn</h3><p>Đối chiếu từ khóa trong hồ sơ với các vị trí và kỹ năng ở tin gần đây.</p><div class="recommendation-links">${list.map(j=>`<button data-detail="${j.id}">${esc(j.title)} ↗</button>`).join('')}</div></div>`:''}
function renderMarketVPJ(){const publicJobs=jobs.filter(j=>j.sourceUrl),recent=publicJobs.filter(j=>j.days<=60);$('#marketMetrics').innerHTML=[[publicJobs.length,'Tin công khai trong kho','▤'],[recent.length,'Tin đăng trong 60 ngày','↗'],[getCompaniesVPJ().length,'Doanh nghiệp / nhóm tin','▦'],[publicJobs.filter(j=>j.positionCount).length,'Tin có vị trí chi tiết','◎']].map(([n,t,i])=>`<div class="market-metric"><span class="metric-icon">${i}</span><div><strong>${n.toLocaleString('vi-VN')}</strong><small>${t}</small></div></div>`).join('')}
async function getDetailsVPJ(j){if(!j.detailShard)return {positions:j.positions||[],skills:j.skills||[],education:j.education||[],salaryStatements:[],images:j.posterUrl?[j.posterUrl]:[]};if(!detailCacheVPJ.has(j.detailShard)){const pending=fetch(j.detailShard+'?v=6').then(r=>{if(!r.ok)throw Error('Detail unavailable');return r.json()}).catch(e=>{detailCacheVPJ.delete(j.detailShard);throw e});detailCacheVPJ.set(j.detailShard,pending)}return (await detailCacheVPJ.get(j.detailShard))[String(j.id)]||{positions:j.positions||[],skills:j.skills||[]}}
function sourceJobLinkVPJ(id){const base=typeof location.href==='string'?location.href:'https://vpj.luuthuy994vp.chatgpt.site/';const u=new URL(base);u.search='';u.searchParams.set('job',id);return u.toString()}
async function shareJobVPJ(id){const j=jobs.find(j=>j.id===id);if(!j)return;const url=sourceJobLinkVPJ(id);try{if(navigator.share){await navigator.share({title:j.title,text:j.company,url});return}if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('Đã sao chép liên kết tin');return}}catch(e){if(e.name==='AbortError')return}openModal(`<h2>Chia sẻ tin tuyển dụng</h2><p>Sao chép liên kết dưới đây.</p><input id="shareLink" readonly value="${esc(url)}" style="width:100%;padding:13px;border:1px solid #dce6f4;border-radius:8px">`);$('#shareLink').focus();$('#shareLink').select()}
detail=async function(id){const j=jobs.find(j=>j.id===id);if(!j?.sourceUrl)return demoDetailVPJ(id);hideSuggestionsVPJ();recentVPJ=[id,...recentVPJ.filter(x=>x!==id)].slice(0,12);write('vpj_recent',recentVPJ);renderActivityVPJ();openModal(`<div class="detail-hero"><div class="job-top">${avatarVPJ(j)}<div><div class="eyebrow">VĨNH PHÚC WORK · TIN CÔNG KHAI</div><h2>${esc(j.title)}</h2><p>${esc(j.company)}</p></div></div></div><div class="metric-skeleton" aria-label="Đang tải chi tiết"></div>`,true);const token=detailRequestVPJ;let d;try{d=await getDetailsVPJ(j)}catch{d={positions:j.positions||[],skills:j.skills||[],education:j.education||[],images:j.posterUrl?[j.posterUrl]:[],salaryStatements:[]}}if(token!==detailRequestVPJ||!$('#modalBack').classList.contains('open'))return;const related=jobs.filter(x=>x.sourceUrl&&x.id!==id&&x.days<=60&&(companyKeyVPJ(x)===companyKeyVPJ(j)||x.category===j.category)).slice(0,4);const tracked=trackerVPJ.some(t=>t.jobId===id);$('#modalContent').innerHTML=`<div class="detail-hero"><div class="job-top">${avatarVPJ(j)}<div><div class="eyebrow">VĨNH PHÚC WORK · TIN CÔNG KHAI</div><h2>${esc(j.title)}</h2><button class="detail-button" data-companyprofile="${esc(companyKeyVPJ(j))}">${esc(j.company)} ↗</button></div></div><div class="detail-meta-grid"><div><small>Địa điểm</small><b>${esc(j.address)}</b></div><div><small>Ngày đăng</small><b>${esc(j.published.split('-').reverse().join('/'))}</b></div><div><small>Hạn tuyển</small><b>${j.deadline?esc(j.deadline)+(deadlineExpiredVPJ(j)?' · Đã qua hạn':''):'Kiểm tra tại nguồn'}</b></div></div></div><div class="detail-toolbar"><a class="btn primary" href="${esc(j.sourceUrl)}" target="_blank" rel="noopener noreferrer">Ứng tuyển tại nguồn ↗</a><button class="btn" data-trackjob="${j.id}">${tracked?'✓ Mở theo dõi':'＋ Theo dõi ứng tuyển'}</button><button class="btn" data-save="${j.id}">${saved.includes(j.id)?'♥ Đã lưu':'♡ Lưu tin'}</button><button class="btn" data-sharejob="${j.id}">↗ Chia sẻ</button></div><div class="detail-section"><h3>Vị trí được nêu trong tin</h3>${d.positions?.length?`<div class="position-list">${d.positions.map((r,i)=>`<div><span>VỊ TRÍ ${String(i+1).padStart(2,'0')}</span>${esc(r)}</div>`).join('')}</div>`:'<p class="source-empty">Bài gốc chưa có tiêu đề vị trí tách riêng. Mở nguồn để đọc đầy đủ.</p>'}</div>${d.salaryStatements?.length?`<div class="detail-section"><h3>Thông tin lương tại nguồn</h3>${d.salaryStatements.map(s=>`<div class="salary-statement">${esc(s)}</div>`).join('')}<p class="page-note">Mỗi mức có thể thuộc một vị trí hoặc bao gồm phụ cấp. Đọc bài gốc để xác định điều kiện áp dụng.</p></div>`:''}<div class="detail-section"><h3>Kỹ năng & trình độ được nhắc đến</h3>${d.skills?.length?`<div class="skill-chips">${d.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div>`:'<p class="source-empty">Chưa có từ khóa kỹ năng được tách từ bài gốc.</p>'}${d.education?.length?`<p class="page-note">Trình độ: ${d.education.map(esc).join(' · ')}</p>`:''}${j.experienceFlags?.length?`<p class="page-note">${esc(j.exp)}. Một tin có thể có yêu cầu khác nhau cho từng vị trí.</p>`:''}</div>${d.images?.length?`<div class="detail-section"><h3>Ảnh tuyển dụng từ nguồn</h3><div class="detail-gallery">${d.images.map(url=>`<button data-jobphoto="${esc(url)}" aria-label="Xem ảnh tuyển dụng"><img src="${esc(url)}" loading="lazy" alt="Ảnh trong tin tuyển dụng ${esc(j.company)}" referrerpolicy="no-referrer"></button>`).join('')}</div></div>`:''}<div class="detail-note">Dữ liệu nhập ngày 11/10/2026. VPJ tách tên vị trí và từ khóa từ nội dung công khai; kiểm tra mô tả, yêu cầu, chế độ và tình trạng tuyển mới nhất tại tin gốc.</div><a class="btn" href="${esc(j.sourceUrl)}" target="_blank" rel="noopener noreferrer">Đọc đầy đủ thông tin tuyển dụng ↗</a>${related.length?`<div class="detail-section"><h3>Cơ hội liên quan</h3><div class="detail-related">${related.map(x=>`<button data-detail="${x.id}"><b>${esc(x.title)}</b>${esc(x.company)} · ${esc(x.location)}</button>`).join('')}</div></div>`:''}`};
const renderBeforeExperienceVPJ=render;
render=function(){renderBeforeExperienceVPJ();renderFilterChipsVPJ();setJobLayoutVPJ(read('vpj_job_layout','grid'));renderActivityVPJ();renderTrackerVPJ()};
const resetBeforeExperienceVPJ=reset;reset=function(){jobTabVPJ='all';selectedCompanyVPJ='';resetBeforeExperienceVPJ();render()};
const openBeforeExperienceVPJ=openModal;openModal=function(content,wide=false){detailRequestVPJ++;openBeforeExperienceVPJ(content,wide)};
const closeBeforeExperienceVPJ=closeModal;closeModal=function(){detailRequestVPJ++;closeBeforeExperienceVPJ()};
function upgradePublicExperienceVPJ(){renderExpandedGuidesVPJ();renderMarketVPJ();renderPublicCompaniesVPJ();renderActivityVPJ();renderTrackerVPJ();renderNotificationBadgeVPJ();renderRecommendationsVPJ();refreshProfileProgressVPJ();render();if(typeof IntersectionObserver!=='undefined'){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal-vpj');observer.unobserve(e.target)}}),{threshold:.1});$$('.spotlight-section,.industry-heading,.career-editorial,.employer-showcase,.faq-section').forEach(e=>observer.observe(e))}try{const id=+new URL(location.href).searchParams.get('job');if(id&&jobs.some(j=>j.id===id))detail(id)}catch{}}
$('#query').oninput=()=>{selectedCompanyVPJ='';visiblePublicJobs=24;clearTimeout(suggestionTimerVPJ);suggestionTimerVPJ=setTimeout(()=>{searchSuggestionsVPJ();render()},180)};$('#query').onfocus=searchSuggestionsVPJ;$('#query').addEventListener('keydown',e=>{if(e.key==='Escape')hideSuggestionsVPJ();if(e.key==='ArrowDown'&&!$('#searchSuggestions').hidden){e.preventDefault();$('#searchSuggestions button')?.focus()}});
$('#searchForm').onsubmit=e=>{e.preventDefault();addSearchHistoryVPJ();hideSuggestionsVPJ();visiblePublicJobs=24;render();$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})};
['location','salaryFilter','experienceFilter','sort','periodFilter'].forEach(id=>$('#'+id).onchange=()=>{visiblePublicJobs=24;render()});$$('.filters input').forEach(e=>e.onchange=()=>{visiblePublicJobs=24;render()});$('#reset').onclick=()=>reset();$('#alertBtn').onclick=saveSearchVPJ;$('#notificationBtn').onclick=showNotificationsVPJ;
$('#companySearch').oninput=()=>{companyLimitVPJ=24;renderPublicCompaniesVPJ()};$('#companyRegion').onchange=()=>{companyLimitVPJ=24;renderPublicCompaniesVPJ()};$('#companyMore').onclick=()=>{companyLimitVPJ+=24;renderPublicCompaniesVPJ()};$('#followingOnly').onclick=()=>{followingOnlyVPJ=!followingOnlyVPJ;$('#followingOnly').setAttribute('aria-pressed',String(followingOnlyVPJ));companyLimitVPJ=24;renderPublicCompaniesVPJ()};$('#trackerFilter').onchange=renderTrackerVPJ;$('#exportTracker').onclick=exportTrackerVPJ;
const profileSubmitBeforeVPJ=$('#profileForm').onsubmit;$('#profileForm').onsubmit=e=>{profileSubmitBeforeVPJ(e);refreshProfileProgressVPJ();renderRecommendationsVPJ()};['profileName','profilePhone','profileEmail','profileSkills','profileJob','profileAbout'].forEach(id=>$('#'+id).addEventListener('input',refreshProfileProgressVPJ));
document.addEventListener('change',e=>{if(e.target.dataset.trackstatus){const t=trackerVPJ.find(t=>t.jobId===+e.target.dataset.trackstatus);if(t&&trackerStatusesVPJ.includes(e.target.value)){t.status=e.target.value;t.updatedAt=new Date().toISOString();write('vpj_tracker',trackerVPJ);renderTrackerVPJ();renderActivityVPJ();toast('Đã cập nhật trạng thái trên thiết bị')}}if(e.target.dataset.tracknote){const t=trackerVPJ.find(t=>t.jobId===+e.target.dataset.tracknote);if(t){t.note=e.target.value.slice(0,1500);t.updatedAt=new Date().toISOString();write('vpj_tracker',trackerVPJ)}}});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const ds=b.dataset;if(ds.view){closeModal();view(ds.view)}if(ds.jobtab){jobTabVPJ=ds.jobtab;visiblePublicJobs=24;render()}if(ds.joblayout)setJobLayoutVPJ(ds.joblayout);if(ds.clearfilter){const map={query:'query',location:'location',salary:'salaryFilter',experience:'experienceFilter'};if(ds.clearfilter==='company')selectedCompanyVPJ='';else if(map[ds.clearfilter])$('#'+map[ds.clearfilter]).value=ds.clearfilter==='salary'?'0':'';else $$('input[name='+ds.clearfilter+']').forEach(x=>{if(x.value===ds.filtervalue)x.checked=false});visiblePublicJobs=24;render()}if(ds.suggestion){$('#query').value=ds.suggestion;visiblePublicJobs=24;addSearchHistoryVPJ();hideSuggestionsVPJ();render();$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})}if(ds.discovery){if(ds.discovery==='companies'||ds.discovery==='tracker'){view(ds.discovery)}else{reset();if(ds.discovery==='none')$('#experienceFilter').value='none';if(ds.discovery==='salary')jobTabVPJ='salary';render();$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})}}if(ds.companyprofile)showCompanyProfileVPJ(ds.companyprofile);if(ds.followcompany)toggleFollowVPJ(ds.followcompany);if(ds.companyjobs){const c=getCompaniesVPJ().find(c=>c.key===ds.companyjobs);if(c){reset();selectedCompanyVPJ=c.key;$('#query').value='';$('#periodFilter').value='all';closeModal();view('jobs');$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})}}if(ds.trackjob)trackJobVPJ(+ds.trackjob);if(ds.untrack){trackerVPJ=trackerVPJ.filter(t=>t.jobId!==+ds.untrack);write('vpj_tracker',trackerVPJ);renderTrackerVPJ();renderActivityVPJ();render()}if(ds.save){$$('#modalContent [data-save]').forEach(x=>{if(x.dataset.save===ds.save)x.textContent=saved.includes(+ds.save)?'♥ Đã lưu':'♡ Lưu tin'})}if(ds.sharejob)shareJobVPJ(+ds.sharejob);if(ds.jobphoto){openModal(`<div class="photo-lightbox"><img src="${esc(ds.jobphoto)}" alt="Ảnh tuyển dụng từ nguồn"></div><a class="btn" href="${esc(ds.jobphoto)}" target="_blank" rel="noopener noreferrer">Mở ảnh đầy đủ ↗</a>`,true)}if('showsavedsearches' in ds)showSearchesVPJ();if(ds.restoresaved)restoreSearchVPJ(+ds.restoresaved);if(ds.deletesaved){searchesVPJ=searchesVPJ.filter(s=>s.id!==+ds.deletesaved);write('vpj_searches',searchesVPJ);renderNotificationBadgeVPJ();showSearchesVPJ()}if(!e.target.closest('#searchForm')&&!e.target.closest('#searchSuggestions'))hideSuggestionsVPJ()});
if(!publicDataReady){$('#jobCards').innerHTML='<div class="loading-jobs">'+Array.from({length:4},()=>'<div class="loading-card"></div>').join('')+'</div>'}else upgradePublicExperienceVPJ();

function renderExpandedGuidesVPJ(){
 const extras=[
 {title:'Ứng tuyển công việc QC / QA',desc:'Chuẩn bị ví dụ về cách kiểm tra, ghi nhận lỗi và xử lý sản phẩm không phù hợp.',body:['Ghi rõ công đoạn đã kiểm: IQC, IPQC, OQC hoặc QA hệ thống.','Liệt kê dụng cụ đo, bản vẽ, tiêu chuẩn và phần mềm bạn đã dùng.','Chuẩn bị một ví dụ lỗi thực tế: phát hiện ở đâu, số lượng, cách cách ly và theo dõi đối sách.','Đọc yêu cầu ca làm, ngoại ngữ và kinh nghiệm của từng vị trí trước khi gửi CV.']},
 {title:'Tìm việc khi chưa có kinh nghiệm',desc:'Chọn vị trí có đào tạo và thể hiện thái độ học hỏi bằng ví dụ cụ thể.',body:['Dùng bộ lọc Không cần kinh nghiệm để tìm tin có nêu rõ điều kiện này.','Ghi kinh nghiệm thực tập, đồ án, việc làm thêm và kỹ năng liên quan.','Tìm hiểu nội dung đào tạo, thời gian thử việc, ca làm và người hướng dẫn.','Không ghi kinh nghiệm bạn chưa có; đưa ra ví dụ về khả năng học việc và làm việc nhóm.']},
 {title:'Đọc mức lương trong tin tuyển dụng',desc:'Phân biệt mức được nêu cho từng vị trí với tổng thu nhập có điều kiện.',body:['Một tin có thể tuyển nhiều vị trí với các mức lương khác nhau.','Kiểm tra lương cơ bản, phụ cấp, tăng ca và thưởng được tính riêng hay đã gộp.','Với khoảng lương, hỏi rõ yếu tố quyết định mức đề nghị.','Mức “từ”, “đến” hoặc “upto” chưa phải là mức bạn chắc chắn nhận được.']},
 {title:'Chuẩn bị phỏng vấn nhà máy',desc:'Tập trung vào công việc thực tế, an toàn và cách phối hợp trong ca sản xuất.',body:['Đọc quy trình, sản phẩm và công đoạn liên quan đến vị trí.','Chuẩn bị ví dụ giải quyết lỗi, bàn giao ca hoặc xử lý một tình huống bất thường.','Hỏi rõ ca làm, tăng ca, phương tiện đi lại và yêu cầu bảo hộ.','Mang CV và tài liệu được yêu cầu; kiểm tra địa chỉ, giờ hẹn trước khi đi.']},
 {title:'Theo dõi hồ sơ sau khi gửi',desc:'Giữ thông tin gọn gàng để biết bạn đã ứng tuyển ở đâu và bước tiếp theo là gì.',body:['Thêm tin vào mục Theo dõi trước hoặc sau khi liên hệ nhà tuyển dụng.','Sau khi gửi CV tại nguồn, tự đổi trạng thái sang Đã gửi hồ sơ.','Ghi ngày gửi, kênh liên hệ và lịch hẹn vào ghi chú.','Cập nhật kết quả sau phỏng vấn, tránh gửi trùng hồ sơ không cần thiết.']}
 ];
 for(const g of extras)if(!guideContentVPJ.some(x=>x.title===g.title))guideContentVPJ.push(g);
 $('#guideGrid').innerHTML=guideContentVPJ.map((g,i)=>`<article class="source-card"><span class="eyebrow">${String(i+1).padStart(2,'0')} / VPJ GUIDE</span><h3>${esc(g.title)}</h3><p>${esc(g.desc)}</p><button class="detail-button" data-expandedguide="${i}">Đọc hướng dẫn ↗</button></article>`).join('');
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-expandedguide]');if(b){const g=guideContentVPJ[+b.dataset.expandedguide];openModal(`<span class="eyebrow">VPJ · CẨM NANG NGHỀ NGHIỆP</span><h2>${esc(g.title)}</h2><p>${esc(g.desc)}</p><ol style="line-height:2;color:#5b7695;font-size:14px;padding-left:22px">${g.body.map(x=>`<li style="padding:8px 0">${esc(x)}</li>`).join('')}</ol><button class="btn primary" data-view="jobs">Khám phá công việc phù hợp ↗</button>`,true)}});

$('#privacyBtn').onclick=()=>openModal('<h2>Dữ liệu & quyền riêng tư</h2><p>Thông tin tuyển dụng hiển thị từ bản nhập công khai của Vĩnh Phúc Work ngày 11/10/2026. Nội dung đầy đủ và liên hệ ứng tuyển mở tại nguồn.</p><p>Hồ sơ, việc đã lưu, công ty theo dõi, tìm kiếm đã lưu, lịch sử xem và nhật ký ứng tuyển được lưu trên trình duyệt này. CV PDF được lưu trong bộ nhớ cục bộ; VPJ chưa tải CV lên máy chủ hoặc gửi cho doanh nghiệp.</p><p>Đăng nhập Google, Facebook, Zalo và OTP hiện là luồng trải nghiệm. Chuông VPJ hiển thị gợi ý trong kho, chưa gửi email/SMS/thông báo đẩy.</p><p>Khi đổi thiết bị hoặc xóa dữ liệu trình duyệt, dữ liệu cá nhân cục bộ có thể không còn. Có thể xuất nhật ký ứng tuyển CSV trước khi đổi thiết bị.</p>');
